13	/// The harnesses' plain-HTTP control ports, over loopback.
14	///
15	/// One implementation, because there were three: each suite had its own private
16	/// `get`/`post` pair, `get` checked the status code in all three and `post`
17	/// checked it in none. A `POST /__mode?front=502` aimed at the wrong server
18	/// therefore returned 404, threw nothing, and the test that depended on it
19	/// asserted against a perfectly healthy dashboard — then hung for two minutes
20	/// waiting for an error page that was never going to appear. A control call
21	/// that does nothing must fail the test that made it.
22	enum HarnessControl {
23	    /// Thrown for any non-2xx. Carries the URL because the usual cause is a
24	    /// path or a port that does not exist on the server being asked.
25	    struct BadStatus: Error, CustomStringConvertible {
26	        let method: String
27	        let url: String
28	        let status: Int
29	        let body: String
30	        var description: String {
31	            "\(method) \(url) answered \(status), not 2xx"
32	                + (body.isEmpty ? "" : ": \(body.prefix(200))")
33	        }
34	    }
35	
36	    static func get(_ url: String, timeout: TimeInterval = 5) async throws -> Data {
37	        try await send("GET", url, timeout: timeout)
38	    }
39	
40	    @discardableResult
41	    static func post(_ url: String, timeout: TimeInterval = 5) async throws -> Data {
42	        try await send("POST", url, timeout: timeout)
43	    }
44	
45	    private static func send(_ method: String, _ url: String,
46	                             timeout: TimeInterval) async throws -> Data {
47	        var request = URLRequest(url: URL(string: url)!, timeoutInterval: timeout)
48	        request.httpMethod = method
49	        let (data, response) = try await URLSession.shared.data(for: request)
50	        let status = (response as? HTTPURLResponse)?.statusCode ?? 0
51	        guard (200...299).contains(status) else {
52	            throw BadStatus(method: method, url: url, status: status,
53	                            body: String(decoding: data, as: UTF8.self))
54	        }
55	        return data
56	    }
57	}
