59	/// Which harness instance a run talks to, and on which ports (F14).
60	///
61	/// Two suite runs at once need two harnesses, so the ports are not constants:
62	/// the suite scripts read an instance's ports from `make ports` and hand them
63	/// to xcodebuild as `TEST_RUNNER_LATCHKEY_<NAME>`, which reach this process as
64	/// `LATCHKEY_<NAME>`. Absent, each is the Makefiles' default (instance 0),
65	/// which is what a single run has always used.
66	enum HarnessInstance {
67	    static let id = ProcessInfo.processInfo.environment["LATCHKEY_HARNESS_INSTANCE"] ?? "0"
68	
69	    static func port(_ name: String, default fallback: Int) -> Int {
70	        guard let raw = ProcessInfo.processInfo.environment["LATCHKEY_\(name)"] else { return fallback }
71	        guard let port = Int(raw), (1...65535).contains(port) else {
72	            preconditionFailure("LATCHKEY_\(name)=\(raw) is not a port")
73	        }
74	        return port
75	    }
76	
77	    /// Fails unless the server behind `stateURL` (a control endpoint whose
78	    /// JSON carries `instance`) is this run's instance. Ports are the only
79	    /// thing keeping two instances apart, and a run that reached its sibling
80	    /// would change modes under the sibling's tests and pass on its journal.
81	    static func assertIsOurs(_ stateURL: String) async throws {
82	        let state = try JSONSerialization.jsonObject(
83	            with: try await HarnessControl.get(stateURL)) as? [String: Any]
84	        let theirs = state?["instance"] as? String ?? "<none>"
85	        guard theirs == id else { throw WrongInstance(url: stateURL, theirs: theirs, ours: id) }
86	    }
87	
88	    struct WrongInstance: Error, CustomStringConvertible {
89	        let url: String, theirs: String, ours: String
90	        var description: String { "\(url) is harness instance \(theirs), not this run's \(ours)" }
91	    }
92	}
