94	extension XCUIElement {
95	    /// `waitForExistence`, polled every 100 ms. XCTest's own wait first looks
96	    /// about a second after it starts and then once a second (F14 §4.1,
97	    /// measured: 1.07 s for an element already on screen), so every wait for
98	    /// something that is there cost a second, dozens of times per suite. Same
99	    /// answer, same timeout; only the polling is finer.
100	    @MainActor
101	    func appears(within timeout: TimeInterval) -> Bool {
102	        let deadline = Date().addingTimeInterval(timeout)
103	        while !exists {
104	            if Date() >= deadline { return false }
105	            Thread.sleep(forTimeInterval: 0.1)
106	        }
107	        return true
108	    }
109	
110	    /// `waitForNonExistence`, polled the same way.
111	    @MainActor
112	    func disappears(within timeout: TimeInterval) -> Bool {
113	        let deadline = Date().addingTimeInterval(timeout)
114	        while exists {
115	            if Date() >= deadline { return false }
116	            Thread.sleep(forTimeInterval: 0.1)
117	        }
118	        return true
119	    }
120	
121	    /// Taps this element once it exists, the app has no presentation or
122	    /// dismissal in progress, and it is hittable; fails the test otherwise.
123	    ///
124	    /// `tap()` alone is not enough, twice over. An element is in the tree from
125	    /// the first frame of the sheet it is on, while UIKit still drops touches,
126	    /// so a tap straight after `appears` can reach nothing. And a tap on an
127	    /// element that is covered (a sheet still over it) synthesizes a touch at
128	    /// {-1, -1} and reports no error, so the failure shows up steps later.
129	    @MainActor
130	    func tapWhenSettled(in app: XCUIApplication, timeout: TimeInterval = 10,
131	                        file: StaticString = #filePath, line: UInt = #line) {
132	        guard appears(within: timeout) else {
133	            XCTFail("\(self) never appeared", file: file, line: line)
134	            return
135	        }
136	        guard app.settles(within: timeout) else {
137	            XCTFail("a presentation was still moving after \(timeout) s; not tapping \(self)", file: file, line: line)
138	            return
139	        }
140	        let deadline = Date().addingTimeInterval(2)
141	        while !isHittable {
142	            if Date() >= deadline {
143	                XCTFail("\(self) is not hittable once settled (covered?)", file: file, line: line)
144	                return
145	            }
146	            Thread.sleep(forTimeInterval: 0.1)
147	        }
148	        tap()
149	    }
