151	    /// Scrolls `container` until this element is on screen. Settings opens as
152	    /// a half sheet, and Forms and Lists build their rows lazily: a row below
153	    /// the fold is not in the tree until it is scrolled to. Slow swipes, and
154	    /// back down if one carried the row past the top.
155	    ///
156	    /// A row below the fold does not appear by waiting, only by swiping, so
157	    /// each step waits half a second rather than the two it used to: that wait
158	    /// was paid in full before every swipe (F14: ~8 s of Status's commit row).
159	    @MainActor
160	    func reveal(scrolling container: XCUIElement, swipes: Int = 8) -> Bool {
161	        for _ in 0..<swipes {
162	            if appears(within: 0.5), isHittable { return true }
163	            if exists, frame.maxY < container.frame.midY {
164	                container.swipeDown(velocity: .slow)
165	            } else {
166	                container.swipeUp(velocity: .slow)
167	            }
168	        }
169	        return appears(within: 2) && isHittable
170	    }
171	}
